export function getExplorerUrl(network: 'mainnet' | 'testnet', address: string) {
  return `${BSC_NETWORKS[network].blockExplorer}/address/${address}`;
}

export function getTxExplorerUrl(network: 'mainnet' | 'testnet', txHash: string) {
  return `${BSC_NETWORKS[network].blockExplorer}/tx/${txHash}`;
}
